add( 'multi-1', '.', '..', '...' );
add( 'multi-2', 'a.', '.a', 'a..b' );
add( 'multi-3', '', '', '' );
add( 'multi-4', map { $D x $_ } 0 .. 7 );
add( 'multi-5', 'xn--.', '.xn--', 'xn--..', '..xn--' );
add( 'multi-6', 'A.B', "\xff.", ".\n." );
