# ---------------------------------------------------------------- runner
sub run_one {
    my ( $prog, $outfile, @args ) = @_;
    my $pid = fork();
    die "fork failed: $!" unless defined $pid;
    if ( $pid == 0 ) {
        open( STDOUT, '>', $outfile ) or POSIX::_exit(126);
        open( STDERR, '>', '/dev/null');
        binmode(STDOUT);
        exec { $prog } ( $prog, @args );
        POSIX::_exit(127);
    }
    waitpid( $pid, 0 );
    return $?;
}

sub slurp {
    my ($f) = @_;
    open( my $fh, '<', $f ) or return undef;
    binmode($fh);
    local $/;
    my $d = <$fh>;
    close($fh);
    return defined($d) ? $d : '';
}

sub hexq { my ($s) = @_; return unpack( 'H*', $s ); }

my $fc = "$SCRATCH/out.cpp";
my $fr = "$SCRATCH/out.rust";
my $mism  = 0;
my $flaky = 0;
my $total = 0;

for my $c (@cases) {
    my ( $label, $args ) = @$c;
    $total++;
    my $rc1 = run_one( $CPP,  $fc, @$args );
    my $o1  = slurp($fc);
    my $rc2 = run_one( $RUST, $fr, @$args );
    my $o2  = slurp($fr);

    next if ( $rc1 == $rc2 && $o1 eq $o2 );

    # confirm reproducibility (twice more)
    my $ok = 1;
    for ( 1 .. 2 ) {
        my $a = run_one( $CPP,  $fc, @$args ); my $ao = slurp($fc);
        my $b = run_one( $RUST, $fr, @$args ); my $bo = slurp($fr);
        $ok = 0 unless ( $a == $rc1 && $ao eq $o1 && $b == $rc2 && $bo eq $o2 );
    }
    unless ($ok) { $flaky++; print "FLAKY $label\n"; next; }

    $mism++;
    my $base = sprintf( "%s/mismatch_%04d", $SCRATCH, $mism );
    open( my $h, '>', "$base.cpp" );  binmode($h); print $h $o1;  close($h);
    open( $h,   '>', "$base.rust" );  binmode($h); print $h $o2;  close($h);
    open( $h,   '>', "$base.argv" );  binmode($h);
    print $h "label=$label\n";
    for my $a (@$args) { print $h 'arg_hex=' . hexq($a) . "\n"; }
    close($h);

    print "MISMATCH $label\n";
    print "  nargs=" . scalar(@$args) . "\n";
    for my $a (@$args) {
        print '  arg_hex=' . hexq($a) . " (len " . length($a) . ")\n";
    }
    printf( "  cpp  status=%d out_hex=%s\n", $rc1, hexq( substr( $o1, 0, 300 ) ) );
    printf( "  rust status=%d out_hex=%s\n", $rc2, hexq( substr( $o2, 0, 300 ) ) );
    print "  cpp  out=" . substr( $o1, 0, 300 ) . "\n";
    print "  rust out=" . substr( $o2, 0, 300 ) . "\n";
    $| = 1;
}

print "TOTAL CASES EXECUTED: $total\n";
print "MISMATCHES: $mism\n";
print "FLAKY: $flaky\n";
